// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 10

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值来自仓库根的 config/thresholds.json（形如 {"shanghai": 20}）。
// 该文件缺失、读不出来、或内容不是 JSON 对象时，回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := readThresholds(resolveThresholdsPath())[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

// resolveThresholdsPath 找到 config/thresholds.json：从当前工作目录逐级向上找，
// 这样无论进程从仓库根还是 inventory/ 下启动都能找到。
func resolveThresholdsPath() string {
	dir, err := os.Getwd()
	if err != nil {
		return filepath.Join("config", "thresholds.json")
	}
	for {
		candidate := filepath.Join(dir, "config", "thresholds.json")
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return filepath.Join("config", "thresholds.json")
		}
		dir = parent
	}
}

// readThresholds 读取并解析阈值文件；任何错误都返回空表，由调用方回退默认值。
func readThresholds(path string) map[string]int {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// 未配置的仓库回退到默认值，且默认值已从 5 调整为 10。
func TestUnconfiguredWarehouseUsesDefaultTen(t *testing.T) {
	if DefaultLowStockThreshold != 10 {
		t.Fatalf("DefaultLowStockThreshold = %d, 期望 10", DefaultLowStockThreshold)
	}
	if got := LowStockThreshold("chengdu"); got != 10 {
		t.Fatalf("LowStockThreshold(%q) = %d, 期望 10", "chengdu", got)
	}
}

// config/thresholds.json 里 shanghai = 20。
func TestConfiguredWarehouseThreshold(t *testing.T) {
	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(%q) = %d, 期望 20", "shanghai", got)
	}
}

func TestIsLowStockUsesConfiguredThreshold(t *testing.T) {
	if !IsLowStock("shanghai", 19) {
		t.Fatal("19 低于 shanghai 的阈值 20，应当算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("20 等于 shanghai 的阈值 20，不算低库存（严格小于）")
	}
}

func TestReadThresholdsParsesObject(t *testing.T) {
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(`{"shanghai": 20}`), 0o600); err != nil {
		t.Fatal(err)
	}
	if got := readThresholds(path); got["shanghai"] != 20 {
		t.Fatalf("readThresholds = %v, 期望 shanghai=20", got)
	}
}

func TestReadThresholdsFallsBackOnBadInput(t *testing.T) {
	dir := t.TempDir()
	write := func(name, content string) string {
		path := filepath.Join(dir, name)
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}

	cases := []struct {
		name string
		path string
	}{
		{"文件不存在", filepath.Join(dir, "missing.json")},
		{"不是 JSON", write("not-json.json", "not json")},
		{"不是 JSON 对象", write("array.json", "[1, 2, 3]")},
		{"JSON null", write("null.json", "null")},
		{"目录读不出来", dir},
	}
	for _, tc := range cases {
		if got := readThresholds(tc.path); len(got) != 0 {
			t.Fatalf("%s: readThresholds = %v, 期望空表", tc.name, got)
		}
	}
}

